const body = $input.first().json;
const data = body.data || body;

const remoteJid = (data.key && data.key.remoteJid) || '';
const phone = remoteJid.replace('@s.whatsapp.net', '').replace('@g.us', '');
const fromMe = (data.key && data.key.fromMe) || false;
const pushName = data.pushName || '';

const messageText = (data.message && (
  data.message.conversation ||
  (data.message.extendedTextMessage && data.message.extendedTextMessage.text) ||
  ''
)) || '';

const isGroup = remoteJid.includes('@g.us');
const textTrim = messageText.trim();
const textLower = textTrim.toLowerCase();

// Comando enviado pelo proprio numero da CaLopes para pausar/ativar o bot nesta conversa
const isCommand = fromMe && !isGroup && (textLower === '/pausar' || textLower === '/ativar');
const isLeadMessage = !fromMe && !isGroup && textTrim.length > 0;

return [{
  json: {
    phone,
    pushName,
    messageText: textTrim,
    fromMe,
    isGroup,
    isCommand,
    command: isCommand ? (textLower === '/ativar' ? 'ativar' : 'pausar') : null,
    isLeadMessage
  }
}];

const staticData = $getWorkflowStaticData('global');
if (!staticData.botStatus) staticData.botStatus = {};

const phone = $json.phone;
const command = $json.command;

staticData.botStatus[phone] = (command === 'ativar');

return [{
  json: {
    phone,
    botAtivo: staticData.botStatus[phone],
    aviso: command === 'pausar'
      ? 'Bot pausado para o contato ' + phone + '.'
      : 'Bot reativado para o contato ' + phone + '.'
  }
}];

const staticData = $getWorkflowStaticData('global');
const status = staticData.botStatus && staticData.botStatus[$json.phone];
const botAtivo = status === undefined ? true : status;

return [{
  json: {
    ...$json,
    botAtivo
  }
}];

const text = $input.first().json.output || '';
const phone = $('Preparar Contexto').first().json.phone;

const parts = text
  .split('\n')
  .map(p => p.trim())
  .filter(p => p.length > 0);

if (parts.length === 0) {
  parts.push(text.trim());
}

return parts.map(parte => ({ json: { mensagem: parte, phone } }));
